  const directory=mkdtempSync(join(tmpdir(),'rgi-cli-'));const db=join(directory,'state.db');
  const invoke=(args:string[])=>{
    const result=spawnSync(process.execPath,['src/cli.ts',...args,'--db',db],{encoding:'utf8',timeout:10000});
